import{_ as i,o as a,c as n,aj as l}from"./chunks/framework.BdtAaXf2.js";const e="/assets/PixPin_2025-04-11_07-54-30.DY5dhh--.gif",p="/assets/image-20250411080012539.C0rYmjQw.png",h="/assets/image-20250411083259055.jcRgY8cZ.png",t="/assets/image-20250411083324095.newxaWlT.png",k="/assets/image-20250411083806523.Dmh3mb-v.png",r="/assets/image-20250411084313893.Bbs3fC_l.png",E="/assets/image-20250411084340843.DlRuAsUd.png",d="/assets/image-20250411084906697.CiUy4vjO.png",g="/assets/image-20250411085117684.i2YRYFXd.png",y="/assets/image-20250411085128503.BJwmewjG.png",c="/assets/image-20250411085137261.BRdZVwj7.png",o="/assets/image-20250411085709994.BY_bvaYj.png",F="/assets/PixPin_2025-04-11_09-09-15.H5KqFHHb.gif",b="/assets/PixPin_2025-04-11_09-11-44.BxVWRaAu.gif",m="/assets/image-20250411091404140.Bf3MfkX6.png",u="/assets/20250411091622.CNzPxwzZ.gif",A="/assets/image-20250411091751524.hLHb71d7.png",C="/assets/image-20250411091856473.CxYV52ZG.png",D="/assets/image-20250411091924788.CcmCg87G.png",B="/assets/image-20250411091937606.BkF7cDx8.png",w=JSON.parse(`{"title":"02-万少带你精读鸿蒙codelabs 一AVPlayer视频播放器","description":"","frontmatter":{},"headers":[],"relativePath":"万少带你精读鸿蒙codelabs/02-万少带你精读鸿蒙codelabs 一AVPlayer视频播放器/02-万少带你精读鸿蒙codelabs 一AVPlayer视频播放器.md","filePath":"万少带你精读鸿蒙codelabs/02-万少带你精读鸿蒙codelabs 一AVPlayer视频播放器/02-万少带你精读鸿蒙codelabs 一AVPlayer视频播放器.md","lastUpdated":1744334711000,"__rawMarkdown":"# 02-万少带你精读鸿蒙codelabs 一AVPlayer视频播放器\\n\\n## 前言\\n\\n本文将深入解析华为开发者联盟 CodeLabs 上的优质基于**AVPlayer实现视频播放器功能——VideoPlayer**。该项目使用ArkTS语言实现视频播放器，主要包括视频获取和视频播放功能：\\n\\n1. **获取本地视频和网络视频。**\\n2. **通过AVPlayer进行视频播放。**\\n3. **通过手势调节屏幕亮度和视频播放音量。**\\n\\n项目地址：https://developer.huawei.com/consumer/cn/codelabsPortal/carddetails/tutorials_NEXT-VideoPlayer\\n\\n\\n\\n## 功能效果演示\\n\\n![PixPin_2025-04-11_07-54-30](assets/PixPin_2025-04-11_07-54-30.gif)\\n\\n## 工程目录\\n\\n![image-20250411080012539](assets/image-20250411080012539.png)\\n\\n\`\`\`\\nets\\n│\\n├─common\\n│  ├─constants\\n│  │  ├─CommonConstants.ets - 定义全局通用常量，如状态码、事件名称等\\n│  │  ├─HomeConstants.ets - 首页相关的常量定义\\n│  │  └─PlayConstants.ets - 播放页面相关的常量定义\\n│  │\\n│  ├─model\\n│  │  ├─HomeTabModel.ets - 首页标签数据模型\\n│  │  └─PlayerModel.ets - 播放器数据模型，存储播放状态、进度、音量等信息\\n│  │\\n│  └─util\\n│     ├─DateFormatUtil.ets - 日期格式化工具，用于转换视频时间显示\\n│     ├─GlobalContext.ets - 全局上下文管理器，用于跨组件数据共享\\n│     ├─Logger.ets - 日志工具类，统一日志输出\\n│     └─ScreenUtil.ets - 屏幕相关工具类，获取屏幕参数\\n│\\n├─controller\\n│  └─VideoController.ets - 视频控制器核心类，负责视频播放的状态管理、手势控制等核心业务逻辑\\n│\\n├─entryability\\n│  └─EntryAbility.ts - 应用入口能力类，负责应用初始化和生命周期管理\\n│\\n├─pages\\n│  ├─HomePage.ets - 首页，展示视频列表\\n│  └─PlayPage.ets - 播放页面，整合播放器各组件\\n│\\n├─view\\n│  ├─HomeTabContent.ets - 首页标签内容组件\\n│  ├─HomeTabContentButton.ets - 首页标签内容按钮组件\\n│  ├─HomeTabContentDialog.ets - 首页对话框组件\\n│  ├─HomeTabContentList.ets - 首页视频列表组件\\n│  ├─HomeTabContentListItem.ets - 首页视频列表项组件\\n│  ├─PlayControl.ets - 播放控制组件，包含播放/暂停、上一个/下一个按钮\\n│  ├─PlayPlayer.ets - 播放器核心渲染组件，集成XComponent\\n│  ├─PlayProgress.ets - 播放进度条组件\\n│  ├─PlayTitle.ets - 播放页面顶部标题组件\\n│  └─PlayTitleDialog.ets - 播放页面标题对话框组件\\n│\\n└─viewmodel\\n   ├─HomeDialogModel.ets - 首页对话框数据模型\\n   ├─HomeVideoListModel.ets - 首页视频列表数据模型\\n   ├─VideoItem.ets - 视频项数据模型\\n   └─VideoSpeed.ets - 视频播放速度数据模型\\n\`\`\`\\n\\n## 业务流程\\n\\n![image-20250411083259055](assets/image-20250411083259055.png)\\n\\n## 首页\\n\\n首页中主要工作就是获取视频，获取本地视频和网络视频\\n\\n![image-20250411083324095](assets/image-20250411083324095.png)\\n\\n首页通过[Tabs](https://developer.huawei.com/consumer/cn/doc/search?val=Tabs&type=all)组件分成了**本地视频**和**网络视频**两个子页面\\n\\n### 本地视频\\n\\n本地视频主要通过扫描raw目录下的，暂时写死文件的视频文件来加载，实际开发中可以调整读取相册视频等方式，或者访问缓存目录。\\n\\n![image-20250411083806523](assets/image-20250411083806523.png)\\n\\n其中**VideoItem**的类型表示为\\n\\n\`\`\`typescript\\n@Observed\\nexport class VideoItem {\\n  name: string;\\n  src: resourceManager.RawFileDescriptor;\\n  iSrc: string;\\n  pixelMap?: image.PixelMap;\\n\\n  constructor(name: string, src: resourceManager.RawFileDescriptor, iSrc: string, pixelMap?: image.PixelMap) {\\n    this.name = name;\\n    this.src = src;\\n    this.iSrc = iSrc;\\n    this.pixelMap = pixelMap;\\n  }\\n}\\n\`\`\`\\n\\n获取到数据之后，存放到了全局中，也可以通过函数返回\\n\\n\`\`\`typescript\\n// HomeVideoListModel.ets\\nasync getLocalVideo() {\\n    this.videoLocalList = [];\\n    await this.assemblingVideoItem();\\n    GlobalContext.getContext().setObject('videoLocalList', this.videoLocalList);\\n    return this.videoLocalList;\\n  }\\n\`\`\`\\n\\n\\n\\n### 网络视频\\n\\n![image-20250411084313893](assets/image-20250411084313893.png)\\n\\n网络视频的获取主要通过[CustomDialogController](https://developer.huawei.com/consumer/cn/doc/search?val=CustomDialogController&type=all)显示弹出层后获取\\n\\n![image-20250411084340843](assets/image-20250411084340843.png)\\n\\n这里的链接校验其实分为两个步骤：\\n\\n1. 校验链接是否为空 \`checkSrcNull\`\\n2. 校验链接是否真的可以播放 \`checkSrcValidity\`，*直接通过创建AVPlayer示例，根据示例的状态来判定*\\n\\n**校验链接是否为空 \`checkSrcNull\`**\\n\\n![image-20250411084906697](assets/image-20250411084906697.png)\\n\\n---\\n\\n![image-20250411085117684](assets/image-20250411085117684.png)\\n\\n---\\n\\n**校验链接是否真的可以播放 \`checkSrcValidity\`，*直接通过创建AVPlayer示例，根据示例的状态来判定***\\n\\n![image-20250411085128503](assets/image-20250411085128503.png)\\n\\n---\\n\\n![image-20250411085137261](assets/image-20250411085137261.png)\\n\\n校验通过后，点击添加，便开始初始化AVPlayer准备播放网络视频。\\n\\n\\n\\n\\n\\n## 视频播放\\n\\n视频播放主要是通过[AVPlayer](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/video-playback)来实现的，一般都根据基于它进行封装，先看使用介绍\\n\\n### 播放步骤\\n\\n1. 调用createAVPlayer()创建AVPlayer实例，初始化进入idle状态。\\n\\n2. 设置业务需要的监听事件，搭配全流程场景使用。支持的监听事件包括：\\n\\n   | 事件类型          | 说明                                                         |\\n   | :---------------- | :----------------------------------------------------------- |\\n   | stateChange       | 必要事件，监听播放器的state属性改变。                        |\\n   | error             | 必要事件，监听播放器的错误信息。                             |\\n   | durationUpdate    | 用于进度条，监听进度条长度，刷新资源时长。                   |\\n   | timeUpdate        | 用于进度条，监听进度条当前位置，刷新当前时间。               |\\n   | seekDone          | 响应API调用，监听seek()请求完成情况。当使用seek()跳转到指定播放位置后，如果seek操作成功，将上报该事件。 |\\n   | speedDone         | 响应API调用，监听setSpeed()请求完成情况。当使用setSpeed()设置播放倍速后，如果setSpeed操作成功，将上报该事件。 |\\n   | volumeChange      | 响应API调用，监听setVolume()请求完成情况。当使用setVolume()调节播放音量后，如果setVolume操作成功，将上报该事件。 |\\n   | bitrateDone       | 响应API调用，用于HLS协议流，监听setBitrate()请求完成情况。当使用setBitrate()指定播放比特率后，如果setBitrate操作成功，将上报该事件。 |\\n   | availableBitrates | 用于HLS协议流，监听HLS资源的可选bitrates，用于setBitrate()。 |\\n   | bufferingUpdate   | 用于网络播放，监听网络播放缓冲信息。                         |\\n   | startRenderFrame  | 用于视频播放，监听视频播放首帧渲染时间。当AVPlayer首次起播进入playing状态后，等到首帧视频画面被渲染到显示画面时，将上报该事件。应用通常可以利用此事件上报，进行视频封面移除，达成封面与视频画面的顺利衔接。 |\\n   | videoSizeChange   | 用于视频播放，监听视频播放的宽高信息，可用于调整窗口大小、比例。 |\\n   | audioInterrupt    | 监听音频焦点切换信息，搭配属性audioInterruptMode使用。如果当前设备存在多个媒体正在播放，音频焦点被切换（即播放其他媒体如通话等）时将上报该事件，应用可以及时处理。 |\\n\\n3. 设置资源：设置属性url，AVPlayer进入initialized状态。\\n\\n   说明\\n\\n   下面代码示例中的url仅作示意使用，开发者需根据实际情况，确认资源有效性并设置：\\n\\n   - 如果使用本地资源播放，必须确认资源文件可用，并使用应用沙箱路径访问对应资源，参考[获取应用文件路径](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/application-context-stage#获取应用文件路径)。应用沙箱的介绍及如何向应用沙箱推送文件，请参考[文件管理](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/app-sandbox-directory)。\\n   - 如果使用网络播放路径，需[声明权限](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/declare-permissions)：ohos.permission.INTERNET。\\n   - 如果使用ResourceManager.getRawFd打开HAP资源文件描述符，使用方法可参考[ResourceManager API参考](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/js-apis-resource-manager#getrawfd9)。\\n   - 需要使用[支持的播放格式与协议](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/media-kit-intro#支持的格式与协议)。\\n\\n4. 设置窗口：获取并设置属性SurfaceID，用于设置显示画面。\\n\\n   应用需要从XComponent组件获取surfaceID，获取方式请参考[XComponent](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-basic-components-xcomponent)。\\n\\n5. 准备播放：调用prepare()，AVPlayer进入prepared状态，此时可以获取duration，设置缩放模式、音量等。\\n\\n6. 视频播控：播放play()，暂停pause()，跳转seek()，停止stop() 等操作。\\n\\n7. （可选）更换资源：调用reset()重置资源，AVPlayer重新进入idle状态，允许更换资源url。\\n\\n8. 退出播放：调用release()销毁实例，AVPlayer进入released状态，退出播放。\\n\\n### AVPlayer播放状态图\\n\\n> 这个状态图很重要，avplayer的播放流程，以及程序封装都需要参考它\\n\\n![image-20250411085709994](assets/image-20250411085709994.png)\\n\\n### 官网示例代码\\n\\n\`\`\`typescript\\nimport { media } from '@kit.MediaKit';\\nimport { fileIo as fs } from '@kit.CoreFileKit';\\nimport { common } from '@kit.AbilityKit';\\nimport { BusinessError } from '@kit.BasicServicesKit';\\n\\nexport class AVPlayerDemo {\\n  private count: number = 0;\\n  private surfaceID: string = ''; // surfaceID用于播放画面显示，具体的值需要通过Xcomponent接口获取，相关文档链接见上面Xcomponent创建方法。\\n  private isSeek: boolean = true; // 用于区分模式是否支持seek操作。\\n  private fileSize: number = -1;\\n  private fd: number = 0;\\n\\n  constructor(surfaceID: string) {\\n    this.surfaceID = surfaceID;\\n  }\\n\\n  // 注册avplayer回调函数。\\n  setAVPlayerCallback(avPlayer: media.AVPlayer) {\\n    // startRenderFrame首帧渲染回调函数。\\n    avPlayer.on('startRenderFrame', () => {\\n      console.info(\`AVPlayer start render frame\`);\\n    });\\n    // seek操作结果回调函数。\\n    avPlayer.on('seekDone', (seekDoneTime: number) => {\\n      console.info(\`AVPlayer seek succeeded, seek time is \${seekDoneTime}\`);\\n    });\\n    // error回调监听函数,当avPlayer在操作过程中出现错误时调用reset接口触发重置流程。\\n    avPlayer.on('error', (err: BusinessError) => {\\n      console.error(\`Invoke avPlayer failed, code is \${err.code}, message is \${err.message}\`);\\n      avPlayer.reset(); // 调用reset重置资源，触发idle状态。\\n    });\\n    // 状态机变化回调函数。\\n    avPlayer.on('stateChange', async (state: string, reason: media.StateChangeReason) => {\\n      switch (state) {\\n        case 'idle': // 成功调用reset接口后触发该状态机上报。\\n          console.info('AVPlayer state idle called.');\\n          avPlayer.release(); // 调用release接口销毁实例对象。\\n          break;\\n        case 'initialized': // avplayer 设置播放源后触发该状态上报。\\n          console.info('AVPlayer state initialized called.');\\n          avPlayer.surfaceId = this.surfaceID; // 设置显示画面，当播放的资源为纯音频时无需设置。\\n          avPlayer.prepare();\\n          break;\\n        case 'prepared': // prepare调用成功后上报该状态机。\\n          console.info('AVPlayer state prepared called.');\\n          avPlayer.play(); // 调用播放接口开始播放。\\n          break;\\n        case 'playing': // play成功调用后触发该状态机上报。\\n          console.info('AVPlayer state playing called.');\\n          if (this.count !== 0) {\\n            if (this.isSeek) {\\n              console.info('AVPlayer start to seek.');\\n              avPlayer.seek(avPlayer.duration); //seek到视频末尾。\\n            } else {\\n              // 当播放模式不支持seek操作时继续播放到结尾。\\n              console.info('AVPlayer wait to play end.');\\n            }\\n          } else {\\n            avPlayer.pause(); // 调用暂停接口暂停播放。\\n          }\\n          this.count++;\\n          break;\\n        case 'paused': // pause成功调用后触发该状态机上报。\\n          console.info('AVPlayer state paused called.');\\n          avPlayer.play(); // 再次播放接口开始播放。\\n          break;\\n        case 'completed': // 播放结束后触发该状态机上报。\\n          console.info('AVPlayer state completed called.');\\n          avPlayer.stop(); //调用播放结束接口。\\n          break;\\n        case 'stopped': // stop接口成功调用后触发该状态机上报。\\n          console.info('AVPlayer state stopped called.');\\n          avPlayer.reset(); // 调用reset接口初始化avplayer状态。\\n          break;\\n        case 'released':\\n          console.info('AVPlayer state released called.');\\n          break;\\n        default:\\n          console.info('AVPlayer state unknown called.');\\n          break;\\n      }\\n    });\\n  }\\n\\n  // 以下demo为使用fs文件系统打开沙箱地址获取媒体文件地址并通过url属性进行播放示例。\\n  async avPlayerUrlDemo() {\\n    // 创建avPlayer实例对象。\\n    let avPlayer: media.AVPlayer = await media.createAVPlayer();\\n    // 创建状态机变化回调函数。\\n    this.setAVPlayerCallback(avPlayer);\\n    let fdPath = 'fd://';\\n    let context = getContext(this) as common.UIAbilityContext;\\n    // 通过UIAbilityContext获取沙箱地址filesDir，以Stage模型为例。\\n    let pathDir = context.filesDir;\\n    let path = pathDir + '/H264_AAC.mp4';\\n    // 打开相应的资源文件地址获取fd，并为url赋值触发initialized状态机上报。\\n    let file = await fs.open(path);\\n    fdPath = fdPath + '' + file.fd;\\n    this.isSeek = true; // 支持seek操作。\\n    avPlayer.url = fdPath;\\n  }\\n\\n  // 以下demo为使用资源管理接口获取打包在HAP内的媒体资源文件并通过fdSrc属性进行播放示例。\\n  async avPlayerFdSrcDemo() {\\n    // 创建avPlayer实例对象。\\n    let avPlayer: media.AVPlayer = await media.createAVPlayer();\\n    // 创建状态机变化回调函数。\\n    this.setAVPlayerCallback(avPlayer);\\n    // 通过UIAbilityContext的resourceManager成员的getRawFd接口获取媒体资源播放地址。\\n    // 返回类型为{fd,offset,length},fd为HAP包fd地址，offset为媒体资源偏移量，length为播放长度。\\n    let context = getContext(this) as common.UIAbilityContext;\\n    let fileDescriptor = await context.resourceManager.getRawFd('H264_AAC.mp4');\\n    let avFileDescriptor: media.AVFileDescriptor =\\n      { fd: fileDescriptor.fd, offset: fileDescriptor.offset, length: fileDescriptor.length };\\n    this.isSeek = true; // 支持seek操作。\\n    // 为fdSrc赋值触发initialized状态机上报。\\n    avPlayer.fdSrc = avFileDescriptor;\\n  }\\n\\n  // 以下demo为使用fs文件系统打开沙箱地址获取媒体文件地址并通过dataSrc属性进行播放(seek模式)示例。\\n  async avPlayerDataSrcSeekDemo() {\\n    // 创建avPlayer实例对象。\\n    let avPlayer: media.AVPlayer = await media.createAVPlayer();\\n    // 创建状态机变化回调函数。\\n    this.setAVPlayerCallback(avPlayer);\\n    // dataSrc播放模式的的播放源地址，当播放为Seek模式时fileSize为播放文件的具体大小，下面会对fileSize赋值。\\n    let src: media.AVDataSrcDescriptor = {\\n      fileSize: -1,\\n      callback: (buf: ArrayBuffer, length: number, pos: number | undefined) => {\\n        let num = 0;\\n        if (buf == undefined || length == undefined || pos == undefined) {\\n          return -1;\\n        }\\n        num = fs.readSync(this.fd, buf, { offset: pos, length: length });\\n        if (num > 0 && (this.fileSize >= pos)) {\\n          return num;\\n        }\\n        return -1;\\n      }\\n    };\\n    let context = getContext(this) as common.UIAbilityContext;\\n    // 通过UIAbilityContext获取沙箱地址filesDir，以Stage模型为例。\\n    let pathDir = context.filesDir;\\n    let path = pathDir + '/H264_AAC.mp4';\\n    await fs.open(path).then((file: fs.File) => {\\n      this.fd = file.fd;\\n    });\\n    // 获取播放文件的大小。\\n    this.fileSize = fs.statSync(path).size;\\n    src.fileSize = this.fileSize;\\n    this.isSeek = true; // 支持seek操作。\\n    avPlayer.dataSrc = src;\\n  }\\n\\n  // 以下demo为使用fs文件系统打开沙箱地址获取媒体文件地址并通过dataSrc属性进行播放(No seek模式)示例。\\n  async avPlayerDataSrcNoSeekDemo() {\\n    // 创建avPlayer实例对象。\\n    let avPlayer: media.AVPlayer = await media.createAVPlayer();\\n    // 创建状态机变化回调函数。\\n    this.setAVPlayerCallback(avPlayer);\\n    let context = getContext(this) as common.UIAbilityContext;\\n    let src: media.AVDataSrcDescriptor = {\\n      fileSize: -1,\\n      callback: (buf: ArrayBuffer, length: number) => {\\n        let num = 0;\\n        if (buf == undefined || length == undefined) {\\n          return -1;\\n        }\\n        num = fs.readSync(this.fd, buf);\\n        if (num > 0) {\\n          return num;\\n        }\\n        return -1;\\n      }\\n    };\\n    // 通过UIAbilityContext获取沙箱地址filesDir，以Stage模型为例。\\n    let pathDir = context.filesDir;\\n    let path = pathDir + '/H264_AAC.mp4';\\n    await fs.open(path).then((file: fs.File) => {\\n      this.fd = file.fd;\\n    });\\n    this.isSeek = false; // 不支持seek操作。\\n    avPlayer.dataSrc = src;\\n  }\\n\\n  // 以下demo为通过url设置网络地址来实现播放直播码流的demo。\\n  async avPlayerLiveDemo() {\\n    // 创建avPlayer实例对象。\\n    let avPlayer: media.AVPlayer = await media.createAVPlayer();\\n    // 创建状态机变化回调函数。\\n    this.setAVPlayerCallback(avPlayer);\\n    this.isSeek = false; // 不支持seek操作。\\n    avPlayer.url = 'http://xxx.xxx.xxx.xxx:xx/xx/index.m3u8'; // 播放hls网络直播码流。\\n  }\\n\\n  // 以下demo为通过setMediaSource设置自定义头域及媒体播放优选参数实现初始播放参数设置。\\n  async preDownloadDemo() {\\n    // 创建avPlayer实例对象。\\n    let avPlayer: media.AVPlayer = await media.createAVPlayer();\\n    let mediaSource : media.MediaSource = media.createMediaSourceWithUrl(\\"http://xxx\\",  {\\"User-Agent\\" : \\"User-Agent-Value\\"});\\n    let playbackStrategy : media.PlaybackStrategy = {preferredWidth: 1, preferredHeight: 2, preferredBufferDuration: 3, preferredHdr: false};\\n    // 设置媒体来源和播放策略。\\n    avPlayer.setMediaSource(mediaSource, playbackStrategy);\\n  }\\n\\n  // 以下demo为通过selectTrack设置音频轨道，通过deselectTrack取消上次设置的音频轨道并恢复到视频默认音频轨道。\\n  async multiTrackDemo() {\\n    // 创建avPlayer实例对象。\\n    let avPlayer: media.AVPlayer = await media.createAVPlayer();\\n    let audioTrackIndex: Object = 0;\\n    avPlayer.getTrackDescription((error: BusinessError, arrList: Array<media.MediaDescription>) => {\\n      if (arrList != null) {\\n        for (let i = 0; i < arrList.length; i++) {\\n          if (i != 0) {\\n            // 获取音频轨道列表。\\n            audioTrackIndex = arrList[i][media.MediaDescriptionKey.MD_KEY_TRACK_INDEX];\\n          }\\n        }\\n      } else {\\n        console.error(\`audio getTrackDescription fail, error:\${error}\`);\\n      }\\n    });\\n    // 选择其中一个音频轨道。\\n    avPlayer.selectTrack(parseInt(audioTrackIndex.toString()));\\n    // 取消选择上次选中的音频轨道，并恢复到默认音频轨道。\\n    avPlayer.deselectTrack(parseInt(audioTrackIndex.toString()));\\n  }\\n}\\n\`\`\`\\n\\n这里看一下当前项目的封装 \`HomeDialogModel.ets\`\\n\\nHomeDialogModel 成员变量\\n| 成员变量 | 类型 | 说明 |\\n| -------- | ---- | ---- |\\n| homeTabModel | HomeTabModel | 首页标签数据模型，用于管理UI状态和数据 |\\n| avPlayer | media.AVPlayer \\\\| null | 视频播放器实例，用于验证视频链接 |\\n| url | string | 存储视频URL地址 |\\n| duration | number | 视频时长，用于判断视频链接有效性 |\\n| checkFlag | number | 检查标志，用于确定是验证还是添加数据（0: 仅验证链接，1: 验证并添加数据） |\\n| isLoading | boolean | 加载状态标志，防止重复操作 |\\nHomeDialogModel 函数\\n| 函数名 | 参数 | 返回值 | 说明 |\\n| ------ | ---- | ------ | ---- |\\n| constructor | 无 | 无 | 构造函数，初始化homeTabModel和isLoading |\\n| createAvPlayer | 无 | 无 | 创建视频播放器对象，设置URL并绑定状态监听 |\\n| bindState | 无 | 无 | 绑定播放器状态变化监听，处理不同状态的回调 |\\n| checkSrcValidity | checkFlag: number | Promise\\\\<void\\\\> | 验证网络连接，检查标志决定是验证还是添加数据 |\\n| checkUrlValidity | 无 | 无 | 验证网络连接，根据duration判断链接有效性 |\\n| failureCallback | error: Error | 无 | 当函数调用发生错误时，用于报告错误信息 |\\n| showPrompt | msg: Resource | 无 | 显示提示对话框，展示验证信息 |\\n| checkSrcNull | 无 | boolean | 检查播放路径是否为空，返回检查结果 |\\n| checkNameNull | 无 | boolean | 检查名称是否为空，返回检查结果 |\\n\\n\`\`\`typescript\\n// HomeDialogModel.ets\\n/*\\n * Copyright (c) 2023 Huawei Device Co., Ltd.\\n * Licensed under the Apache License, Version 2.0 (the \\"License\\");\\n * you may not use this file except in compliance with the License.\\n * You may obtain a copy of the License at\\n *\\n *     http://www.apache.org/licenses/LICENSE-2.0\\n *\\n * Unless required by applicable law or agreed to in writing, software\\n * distributed under the License is distributed on an \\"AS IS\\" BASIS,\\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n * See the License for the specific language governing permissions and\\n * limitations under the License.\\n */\\n\\nimport { promptAction } from \\"@kit.ArkUI\\";\\nimport { media } from \\"@kit.MediaKit\\";\\nimport Logger from \\"../common/util/Logger\\";\\nimport { HomeConstants } from \\"../common/constants/HomeConstants\\";\\nimport { AvplayerStatus, Events } from \\"../common/constants/CommonConstants\\";\\nimport { HomeTabModel } from \\"../common/model/HomeTabModel\\";\\n\\nexport class HomeDialogModel {\\n  /**\\n   * 首页标签数据模型，用于管理UI状态和数据\\n   */\\n  public homeTabModel: HomeTabModel;\\n\\n  /**\\n   * 视频播放器实例，用于验证视频链接\\n   */\\n  private avPlayer: media.AVPlayer | null = null;\\n\\n  /**\\n   * 存储视频URL地址\\n   */\\n  private url: string = \\"\\";\\n\\n  /**\\n   * 视频时长，用于判断视频链接有效性\\n   */\\n  private duration: number = 0;\\n\\n  /**\\n   * 检查标志，用于确定是验证还是添加数据\\n   * 0: 仅验证链接\\n   * 1: 验证并添加数据\\n   */\\n  private checkFlag: number = 0;\\n\\n  /**\\n   * 加载状态标志，防止重复操作\\n   */\\n  private isLoading: boolean = false;\\n\\n  constructor() {\\n    this.homeTabModel = new HomeTabModel();\\n    this.isLoading = false;\\n  }\\n\\n  /**\\n   * 创建视频播放器对象。\\n   */\\n  createAvPlayer() {\\n    media\\n      .createAVPlayer()\\n      .then((video: media.AVPlayer) => {\\n        if (video != null) {\\n          this.avPlayer = video;\\n          this.bindState();\\n          this.url = this.homeTabModel.src;\\n          this.avPlayer.url = this.url;\\n        } else {\\n          Logger.info(\`[HomeDialogModel] createAVPlayer fail\`);\\n        }\\n      })\\n      .catch((err: Error) => {\\n        this.failureCallback(err);\\n      });\\n  }\\n\\n  /**\\n   * 绑定播放器状态变化监听\\n   */\\n  bindState() {\\n    if (this.avPlayer === null) {\\n      return;\\n    }\\n    this.avPlayer.on(\\n      Events.STATE_CHANGE,\\n      async (state: media.AVPlayerState) => {\\n        if (this.avPlayer === null) {\\n          return;\\n        }\\n        if (state === AvplayerStatus.INITIALIZED) {\\n          this.avPlayer.prepare();\\n        } else if (state === AvplayerStatus.PREPARED) {\\n          this.duration = this.avPlayer.duration;\\n          this.checkUrlValidity();\\n        } else if (state === AvplayerStatus.ERROR) {\\n          this.avPlayer.reset();\\n        }\\n      }\\n    );\\n    this.avPlayer.on(Events.ERROR, (error: Error) => {\\n      this.isLoading = false;\\n      this.homeTabModel.linkCheck = $r(\\"app.string.link_check\\");\\n      this.homeTabModel.loadColor = $r(\\n        \\"app.color.index_tab_selected_font_color\\"\\n      );\\n      if (this.avPlayer !== null) {\\n        this.avPlayer.release();\\n      }\\n      this.failureCallback(error);\\n    });\\n  }\\n\\n  /**\\n   * 验证网络连接。\\n   *\\n   * @param checkFlag 确定是验证还是添加数据。\\n   */\\n  async checkSrcValidity(checkFlag: number) {\\n    if (this.isLoading) {\\n      return;\\n    }\\n    this.isLoading = true;\\n    this.homeTabModel.linkCheck = $r(\\"app.string.link_checking\\");\\n    this.homeTabModel.loadColor = $r(\\n      \\"app.color.index_tab_unselected_font_color\\"\\n    );\\n    this.checkFlag = checkFlag;\\n    this.createAvPlayer();\\n  }\\n\\n  /**\\n   * 验证网络连接。\\n   */\\n  checkUrlValidity() {\\n    this.isLoading = false;\\n    this.homeTabModel.linkCheck = $r(\\"app.string.link_check\\");\\n    this.homeTabModel.loadColor = $r(\\"app.color.index_tab_selected_font_color\\");\\n    if (this.avPlayer !== null) {\\n      this.avPlayer.release();\\n    }\\n    if (this.duration === HomeConstants.DURATION_TWO) {\\n      // 链接验证失败\\n      this.showPrompt($r(\\"app.string.link_check_fail\\"));\\n    } else if (this.duration === HomeConstants.DURATION_ONE) {\\n      // 地址不正确或网络不可用\\n      this.showPrompt($r(\\"app.string.link_check_address_internet\\"));\\n    } else {\\n      this.duration = 0;\\n      if (this.checkFlag === 0) {\\n        this.showPrompt($r(\\"app.string.link_check_success\\"));\\n      } else {\\n        this.homeTabModel!.confirm();\\n        this.homeTabModel!.controller!.close();\\n      }\\n    }\\n  }\\n\\n  /**\\n   * 当函数调用发生错误时，用于报告错误信息。\\n   *\\n   * @param error 错误信息。\\n   */\\n  failureCallback(error: Error) {\\n    Logger.error(\`[HomeDialogModel] error happened: \` + JSON.stringify(error));\\n    this.showPrompt($r(\\"app.string.link_check_fail\\"));\\n  }\\n\\n  /**\\n   * 提示对话框。\\n   *\\n   * @param msg 验证信息。\\n   */\\n  showPrompt(msg: Resource) {\\n    promptAction.showToast({\\n      duration: HomeConstants.DURATION,\\n      message: msg,\\n    });\\n  }\\n\\n  /**\\n   * 检查播放路径是否为空。\\n   */\\n  checkSrcNull(): boolean {\\n    if (this.isLoading) {\\n      return false;\\n    }\\n    if (this.homeTabModel.src.trim() === \\"\\") {\\n      promptAction.showToast({\\n        duration: HomeConstants.DURATION,\\n        message: $r(\\"app.string.place_holder_src\\"),\\n      });\\n      return false;\\n    }\\n    return true;\\n  }\\n\\n  /**\\n   * 检查名称是否为空。\\n   */\\n  checkNameNull(): boolean {\\n    if (this.isLoading) {\\n      return false;\\n    }\\n    if (this.homeTabModel.name.trim() === \\"\\") {\\n      promptAction.showToast({\\n        duration: HomeConstants.DURATION,\\n        message: $r(\\"app.string.place_holder_name\\"),\\n      });\\n      return false;\\n    }\\n    return true;\\n  }\\n}\\n\\n\`\`\`\\n\\n## 手势控制\\n\\n手势控制[gesture](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/gesture-processing-V5)的功能主要体现在控制播放视频时屏幕的亮度上和音量大小上\\n\\n**上下滑动是控制屏幕亮度**\\n\\n![PixPin_2025-04-11_09-09-15](assets/PixPin_2025-04-11_09-09-15.gif)\\n\\n**左右滑动是控制音量大小**\\n\\n![PixPin_2025-04-11_09-11-44](assets/PixPin_2025-04-11_09-11-44.gif)\\n\\n---\\n\\nArkUI中提供了常见的手势控制方案，其中这里使用的是[PanGesture](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ts-basic-gestures-pangesture-V5)-拖动手势\\n\\n![image-20250411091404140](assets/image-20250411091404140.png)\\n\\n\`\`\`typescript\\nPanGesture(value?:{ fingers?:number, direction?:PanDirection, distance?:number})\\n\`\`\`\\n\\n拖动手势用于触发拖动手势事件，滑动达到最小滑动距离（默认值为5vp）时拖动手势识别成功，拥有三个可选参数：\\n\\n- fingers：用于声明触发拖动手势所需要的最少手指数量，最小值为1，最大值为10，默认值为1。\\n- direction：用于声明触发拖动的手势方向，此枚举值支持逻辑与（&）和逻辑或（|）运算。默认值为Pandirection.All。\\n- distance：用于声明触发拖动的最小拖动识别距离，单位为vp，默认值为5。\\n\\n基本示例：\\n\\n\`\`\`typescript\\n// xxx.ets\\n@Entry\\n@Component\\nstruct Index {\\n  @State offsetX: number = 0;\\n  @State offsetY: number = 0;\\n  @State positionX: number = 0;\\n  @State positionY: number = 0;\\n\\n  build() {\\n    Column() {\\n      Text('PanGesture Offset:\\\\nX: ' + this.offsetX + '\\\\n' + 'Y: ' + this.offsetY)\\n        .fontSize(28)\\n        .height(200)\\n        .width(300)\\n        .padding(20)\\n        .border({ width: 3 })\\n          // 在组件上绑定布局位置信息\\n        .translate({ x: this.offsetX, y: this.offsetY, z: 0 })\\n        .gesture(\\n          // 绑定拖动手势\\n          PanGesture()\\n           .onActionStart((event: GestureEvent|undefined) => {\\n              console.info('Pan start');\\n            })\\n              // 当触发拖动手势时，根据回调函数修改组件的布局位置信息\\n            .onActionUpdate((event: GestureEvent|undefined) => {\\n              if(event){\\n                this.offsetX = this.positionX + event.offsetX;\\n                this.offsetY = this.positionY + event.offsetY;\\n              }\\n            })\\n            .onActionEnd(() => {\\n              this.positionX = this.offsetX;\\n              this.positionY = this.offsetY;\\n            })\\n        )\\n    }\\n    .height(200)\\n    .width(250)\\n  }\\n}\\n\`\`\`\\n\\n![20250411091622](assets/20250411091622.gif)\\n\\n\\n\\n\\n\\n当前项目中的用法，如音量大小，分别在拖动的开始、过程、结束中进行业务处理。\\n\\n![image-20250411091751524](assets/image-20250411091751524.png)\\n\\n比如将拖动的距离和音量进行相关联\\n\\n![image-20250411091856473](assets/image-20250411091856473.png)\\n\\n![image-20250411091924788](assets/image-20250411091924788.png)\\n\\n![image-20250411091937606](assets/image-20250411091937606.png)\\n\\n## 总结\\n\\n\\n\\n### 主要功能\\n\\n本视频播放器实现了以下主要功能：\\n\\n1. **基本播放控制**：播放、暂停、上一个、下一个\\n2. **进度控制**：进度条拖动、显示当前时间和总时间\\n3. **手势控制**：\\n   - 垂直滑动调节屏幕亮度\\n   - 水平滑动调节视频播放音量\\n4. **多视频源支持**：支持本地视频和网络视频播放\\n5. **自适应布局**：根据视频尺寸自动调整播放器布局\\n\\n### 技术特点\\n\\n1. **状态管理**：通过监听 AVPlayer 的状态变化实现复杂的播放控制逻辑\\n2. **高性能渲染**：使用 XComponent 实现高性能视频渲染\\n3. **手势识别**：通过 PanGesture 实现直观的手势控制\\n4. **模块化设计**：将 UI 和业务逻辑分离，提高代码可维护性\\n\\n\\n\\n如果你兴趣想要了解更多的开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。"}`),f={name:"万少带你精读鸿蒙codelabs/02-万少带你精读鸿蒙codelabs 一AVPlayer视频播放器/02-万少带你精读鸿蒙codelabs 一AVPlayer视频播放器.md"};function P(v,s,x,S,_,V){return a(),n("div",null,[...s[0]||(s[0]=[l("",80)])])}const I=i(f,[["render",P]]);export{w as __pageData,I as default};
